class Solution {
public:
    int minCost(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<int> dp(n + 1, 2e9);
        dp[0] = 0;
        std::vector<int> counts(n, 0);
        for (int i = 1; i <= n; ++i) {
            std::fill(counts.begin(), counts.end(), 0);
            int trimmed = 0;
            for (int j = i - 1; j >= 0; --j) {
                int x = nums[j];
                counts[x]++;
                if (counts[x] == 2) trimmed += 2;
                else if (counts[x] > 2) trimmed++;
                dp[i] = std::min(dp[i], dp[j] + k + trimmed);
            }
        }
        return dp[n];
    }
};

class Solution {
    public int minCost(int[] nums, int k) {
        int n = nums.length;
        int[] dp = new int[n + 1];
        java.util.Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        int[] counts = new int[n];
        for (int i = 1; i <= n; i++) {
            java.util.Arrays.fill(counts, 0);
            int trimmed = 0;
            for (int j = i - 1; j >= 0; j--) {
                int x = nums[j];
                counts[x]++;
                if (counts[x] == 2) trimmed += 2;
                else if (counts[x] > 2) trimmed++;
                dp[i] = Math.min(dp[i], dp[j] + k + trimmed);
            }
        }
        return dp[n];
    }
}

var minCost = function(nums, k) {
    const n = nums.length;
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;
    const counts = new Int32Array(n);
    for (let i = 1; i <= n; i++) {
        counts.fill(0);
        let trimmed = 0;
        for (let j = i - 1; j >= 0; j--) {
            const x = nums[j];
            counts[x]++;
            if (counts[x] === 2) trimmed += 2;
            else if (counts[x] > 2) trimmed++;
            const cost = dp[j] + k + trimmed;
            if (cost < dp[i]) dp[i] = cost;
        }
    }
    return dp[n];
};
